//! Cargo-driven `user32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is user32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x77a20000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ffb2000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ffb2000000u64)),
        o => panic!("user32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:win32ksys", "engine:pseh", "body", "import:usp10", "import:libpng", "import:gdi32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:crate:user32_vista-rust::TRUE", "engine:crate:user32_optional_vista-rust::TRUE", "engine:crate:user32-wsprintf-rust::TRUE", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["engine:wine", "engine:c:win32ksys", "engine:pseh", "body", "import:usp10", "import:libpng", "import:gdi32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:crate:user32_vista-rust::TRUE", "engine:crate:user32_optional_vista-rust::TRUE", "engine:crate:user32-wsprintf-rust::TRUE", "engine:delayimp_rust"],
        "aarch64" => &["engine:wine", "engine:c:win32ksys", "engine:pseh", "body", "import:usp10", "import:libpng", "import:gdi32", "import:advapi32", "import:kernel32", "import:ntdll", "engine:crate:user32_vista-rust::TRUE", "engine:crate:user32_optional_vista-rust::TRUE", "engine:crate:user32-wsprintf-rust::TRUE", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/win32ss/user/user32",
        "win32ss/user/user32",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/subsys",
        "win32ss/user/user32/include",
        "sdk/include/wine",
        "win32ss/include",
        "sdk/lib/pseh/include",
        "vendor/zlib/include",
        "sdk/lib/tdilib",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("user32-rust")
        .c_from_compile_db(
            "user32_shims",
            match arch.as_str() {
                "x86" => &["win32ss/user/user32/windows/wndproc_fixup.S"],
                "x86_64" => &[],
                "aarch64" => &[],
                _ => unreachable!(),
            },
        )
        .rc("win32ss/user/user32/user32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("win32ss/user/user32/user32.spec", "user32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/usp10/usp10.spec", "usp10.dll", "usp10")
        .delay_import_lib("vendor/libpng/libpng.spec", "libpng.dll", "libpng")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
